# Mine floor layout B (floors 1, 4, 7, ...): two chambers joined by a gap in a rock wall.
map MINE_B set=MINE w=16 h=16 music=MINE
key c MINE_CEIL block
key # MINE_WALL block
key t MINE_WALL_TORCH block
key . MINE_FLOOR walk
key , MINE_FLOOR2 walk
key _ MINE_FLOOR3 walk
key U MINE_LADDER_UP block
key ~ MINE_PUDDLE water
key p MINE_PILLAR block
grid
cccccccccccccccc
c#t#U##ccc#_#t#c
c,.____###.____c
c..._.,.,..___.c
c.,.......,....c
c......p.....,.c
c.,..........,.c
ccccccc...cccccc
c######...######
c..,..........,c
c.~~...,...p...c
c.~~.......,...c
c......,.......c
c.,.p.....,..,.c
c.......,......c
cccccccccccccccc
place MINE_LIFT 11 1 act=LIFT
act 4 1 LADDERUP
